set -e
git fetch {upstream_remote} {upstream_branch}
if git merge --no-edit {upstream_remote}/{upstream_branch}; then
  exit 0
fi
git rev-parse -q --verify MERGE_HEAD >/dev/null
tmpdir=$(mktemp -d)
trap 'rm -rf "$tmpdir"' EXIT
while IFS= read -r -d '' path; do
  base="$tmpdir/base"
  ours="$tmpdir/ours"
  theirs="$tmpdir/theirs"
  merged="$tmpdir/merged"
  git show ":1:$path" > "$base"
  git show ":2:$path" > "$ours"
  git show ":3:$path" > "$theirs"
  python3 - "$base" "$ours" "$theirs" "$merged" <<'PY'
import sys
import difflib

base_path, ours_path, theirs_path, out_path = sys.argv[1:5]

def read_lines(path):
    with open(path, "r", encoding="utf-8", errors="surrogateescape") as f:
        return f.readlines()

base = read_lines(base_path)
ours = read_lines(ours_path)
theirs = read_lines(theirs_path)

def get_opcodes(a, b):
    return difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes()

# Map each base-line boundary to the corresponding boundary in theirs.
mapping = [0] * (len(base) + 1)
upstream_inserts = {}
for tag, i1, i2, j1, j2 in get_opcodes(base, theirs):
    if tag == "equal":
        for k in range(i1, i2 + 1):
            mapping[k] = j1 + (k - i1)
    elif tag == "insert":
        mapping[i1] = max(mapping[i1], j2)
        if i1 not in upstream_inserts or j1 < upstream_inserts[i1]:
            upstream_inserts[i1] = j1
    else:  # replace or delete
        mapping[i1] = j1
        mapping[i2] = j2
        for k in range(i1 + 1, i2):
            mapping[k] = j1

# Keep the mapping monotonic and fill any unset boundaries.
for i in range(1, len(mapping)):
    if mapping[i] < mapping[i - 1]:
        mapping[i] = mapping[i - 1]

# Local pure insertions are the changes we re-apply.
insertions = []
for tag, i1, i2, j1, j2 in get_opcodes(base, ours):
    if tag == "insert":
        insertions.append((i1, ours[j1:j2]))

def already_present(block, lines):
    n = len(block)
    if n == 0:
        return True
    for k in range(len(lines) - n + 1):
        if lines[k:k + n] == block:
            return True
    return False

by_pos = {}
for base_idx, block in insertions:
    if already_present(block, theirs):
        continue
    pos = upstream_inserts.get(base_idx, mapping[base_idx])
    by_pos.setdefault(pos, []).append(block)

out = []
for j in range(len(theirs) + 1):
    for block in by_pos.get(j, []):
        out.extend(block)
    if j < len(theirs):
        out.append(theirs[j])

with open(out_path, "w", encoding="utf-8", errors="surrogateescape") as f:
    f.writelines(out)
PY
  cat "$merged" > "$path"
  git add -- "$path"
done < <(git diff --name-only --diff-filter=U -z)
git commit --no-edit
